local function parseByteArray(text)
  if type(text)~='string' then
    return nil
  end

  local body=text:match('^%s*{%s*(.-)%s*}%s*$')

  if not body then
    return nil
  end

  local bytes=U.array()

  for token in body:gmatch('[^,]+') do
    token=U.trim(token)

    local hex=token:match('^0[xX]([%x]+)$')
    local dec=token:match('^(%d+)$')
    local value

    if hex then
      value=tonumber(hex,16)
    elseif dec then
      value=tonumber(dec,10)
    else
      return nil
    end

    if not value or value<0 or value>255 then
      return nil
    end

    bytes[#bytes+1]=value
  end

  if #bytes==0 then
    return nil
  end

  return bytes
end

local function inspectLuaHook(text,script,report,line,section)
  if type(text)~='string' then
    return
  end

  local module=text:match(
    "local%s+base%s*=%s*getAddress%s*%(%s*['\"]([^'\"]+)['\"]%s*%)"
  )

  local rvaHex=text:match(
    'local%s+source%s*=%s*base%s*%+%s*0[xX]([%x]+)'
  )

  local rvaDec=text:match(
    'local%s+source%s*=%s*base%s*%+%s*(%d+)'
  )

  if not module or not rvaHex and not rvaDec then
    return
  end

  local rva

  if rvaHex then
    rva=tonumber(rvaHex,16)
  else
    rva=tonumber(rvaDec,10)
  end

  if not rva then
    return
  end

  local expectedText=text:match(
    'local%s+expected%s*=%s*({.-})'
  )

  local originalText=text:match(
    'local%s+original%s*=%s*({.-})'
  )

  local expected=parseByteArray(expectedText)
  local original=parseByteArray(originalText)

  report.resources[#report.resources+1]={
    script_id=script.id,
    line=line,
    section=section,
    command='lua_rva_hook',
    arguments=U.array({
      module,
      string.format('0x%X',rva)
    }),
    ownership='unverified',
    lifecycle='unverified',
    hook={
      kind='lua_rva_hook',
      module=module,
      rva=string.format('0x%X',rva),
      expected_bytes=expected and #expected or U.null,
      original_bytes=original and #original or U.null,
      expected=expected or U.null,
      original=original or U.null,
      dynamic_aa=text:find('autoAssemble',1,true)~=nil,
      allocation=text:find('allocateMemory',1,true)~=nil
    }
  }

  U.warn(
    report,
    'LUA-RVA-HOOK',
    'Static module+RVA hook candidate detected lexically; runtime Lua was not executed.',
    script.id,
    line
  )
end

local scopes={
  aobscan='process',
  aobscanmodule='module'
}

local counts={
  aobscan=2,
  aobscanmodule=3
}

-- Deliberately narrow: no quoted names, expressions, macros or numeric addresses.
local function dependency(report,script,row,section,command,name,kind,relation)
  if not name or not name:match('^[A-Za-z_][A-Za-z0-9_]*$') or name:match('^%x+$') then
    return
  end
  report.dependencies[#report.dependencies+1]={
    script_id=script.id,line=row.line,section=section,command=command,
    name=name,kind=kind,relation=relation,source='lexical',status='unverified'
  }
end

local function commandDependencies(report,script,row,section,cmd,args)
  local function add(name,kind,relation)
    dependency(report,script,row,section,cmd,name,kind,relation)
  end
  if scopes[cmd] and #args==counts[cmd] then
    add(args[1],'symbol','provides')
  elseif cmd=='define' and #args==2 then
    add(args[1],'symbol','provides')
    add(args[2],'symbol','requires')
  elseif cmd=='label' and #args==1 then
    add(args[1],'symbol','provides')
  elseif (cmd=='alloc' and (#args==2 or #args==3))
    or (cmd=='globalalloc' and #args==2) then
    add(args[1],'resource','provides')
    add(args[1],'symbol','provides')
    if args[3] then add(args[3],'symbol','requires') end
  elseif cmd=='registersymbol' or cmd=='unregistersymbol' then
    for _,name in ipairs(args) do
      add(name,'symbol','requires')
      if cmd=='registersymbol' then add(name,'registered_symbol','provides') end
    end
  elseif cmd=='dealloc' and #args==1 then
    add(args[1],'resource','requires')
  end
end

function M.inspect(script,report)
  report.dependencies=report.dependencies or U.array()
  local section,disable,disableContent='common',false,false
  local lines=M.lines(script.text)

  script.labels=U.array()
  script.defines={}
  script.dynamic=false

  local luaText,luaLine={},nil
  local luaSection=section

  local function flushLua()
    if luaLine then
      local text=table.concat(luaText,'\n')
      luaDependencies(text,script,report,luaLine,luaSection)

      local embedded={
        id=script.id..'-lua-'..luaLine,
        language='Lua',
        text=text,
        origin='embedded',
        parent_script_id=script.id,
        record_key=script.record_key,
        line=luaLine
      }

      report.scripts[#report.scripts+1]=embedded

      inspectLuaHook(
        text,
        script,
        report,
        luaLine,
        luaSection
      )

      luaText={}
      luaLine=nil
    end
  end

  for _,row in ipairs(lines) do
    local s=row.text

    if row.directive=='opaque' then
      flushLua()
      script.dynamic=true
      if row.note=='SECTION-INDETERMINATE' then section='unknown' end
      if section=='disable' then disableContent=true end
      U.warn(report,row.note,'Opaque source; conditional branches are not evaluated and no execution semantics are inferred.',script.id,row.line)
    elseif row.luaSection then
      flushLua()
      section=s:lower():sub(2,-2)
      if section=='disable' then disable=true end
      luaSection=section
      luaLine=row.line+1

    elseif row.directive=='lua' then
      flushLua()
      luaSection=section
      script.dynamic=true
      luaLine=row.line+1

      if section=='disable' then
        disableContent=true
      end

    elseif row.lua then
      if section=='disable' and U.trim(row.lua)~='' then disableContent=true end
      luaText[#luaText+1]=row.lua

    elseif row.directive=='asm' then
      flushLua()

    elseif s:upper()=='[ENABLE]' then
      section='enable'

    elseif s:upper()=='[DISABLE]' then
      section='disable'
      disable=true

    elseif s~='' then
      if section=='disable' then
        disableContent=true
      end

      local cmd,raw=s:match('^([%w_]+)%s*%((.*)%)%s*$')
      cmd=cmd and cmd:lower()
      local args=raw and M.arguments(raw)
      local opaqueCommand=s:lower():match('^([%w_]+)%s*%(')
      if opaqueCommand=='hook' or opaqueCommand=='unhook' or opaqueCommand=='hook5'
        or opaqueCommand=='aobscanfunction' or opaqueCommand=='aobscanregion' then
        script.dynamic=true
        U.warn(report,'OPAQUE-COMMAND','Post-source command '..opaqueCommand..' observed lexically; unsupported semantics.',script.id,row.line)
        cmd=nil;args=nil;s=''
      end
      if cmd then commandDependencies(report,script,row,section,cmd,args) end

      if scopes[cmd] then
        local id='aob-'..(#report.aobs+1)

        report.aobs[#report.aobs+1]={
          id=id,
          script_id=script.id,
          line=row.line,
          section=section,
          command=cmd,
          arguments=args,
          symbol=args[1],
          scope=scopes[cmd],
          pattern=args[#args],
          syntax_supported=#args==counts[cmd],
          status='not_scanned',
          match_count=U.null,
          uniqueness='unverified',
          cross_build_robustness='unverified',
          matches=U.array(),
          matches_truncated=false,
          hook_candidates=U.array(),
          source_applicability='lexical_only'
        }

      elseif cmd=='define' and #args==2 and section~='disable' then
        local key=args[1]:lower()

        if script.defines[key]~=nil then
          script.defines[key]=false
        else
          script.defines[key]=args[2]
        end

      elseif cmd=='alloc'
        or cmd=='globalalloc'
        or cmd=='dealloc'
        or cmd=='registersymbol'
        or cmd=='unregistersymbol'
      then
        report.resources[#report.resources+1]={
          script_id=script.id,
          line=row.line,
          section=section,
          command=cmd,
          arguments=args,
          ownership='unverified',
          lifecycle='unverified'
        }

        if cmd=='dealloc' then
          U.warn(
            report,
            'RESTORE-BEFORE-FREE',
            'Review full byte restoration and in-flight execution before free; lexical order is not proof.',
            script.id,
            row.line
          )
        end

        if (cmd=='dealloc' or cmd=='unregistersymbol')
          and (raw=='' or raw:find('*',1,true))
        then
          U.warn(
            report,
            'RESOURCE-OWNERSHIP',
            'Broad cleanup candidate; ownership is unverified.',
            script.id,
            row.line
          )
        end

      elseif cmd=='include'
        or cmd=='luacall'
        or s:find('{$',1,true)
      then
        script.dynamic=true
      end

      local label=s:match('^(.-):$')

      if label then
        dependency(report,script,row,section,'address_label',U.trim(label),'symbol','requires')
      end

      if label and section~='disable' then
        script.labels[#script.labels+1]={
          expression=U.trim(label),
          line=row.line
        }
      end
    end
  end

  flushLua()

  if disable and not disableContent then
    U.warn(
      report,
      'EMPTY-DISABLE',
      'Empty DISABLE may intentionally keep a persistent library installed.',
      script.id
    )
  end

  if script.dynamic then
    U.warn(
      report,
      'DYNAMIC-SOURCE',
      'Lua/includes/preprocessor may change AA. Literal scans are lexical observations, not compiled-script equivalence.',
      script.id
    )
  end
end

return M

end
factories['semantics'] = function(require, api)
-- Evidence metadata only: no CE API calls, capability detection or source execution.
local U=require('util')
local M={}
function M.profile(ce_version)
  local function note(id,version,feature)
    return {id=id,version=version,feature=feature,
      evidence_kind='release_note_evidence',evidence_ref='user-chronology/'..version,
      runtime_validation='not_performed'}
  end
  return {
    profile_version='1',profile_id='ce-public-ec45d5f-to-runtime-r1',
    source_profile={repository='https://github.com/cheat-engine/cheat-engine',
      commit='ec45d5f47f92a239ba0bf51ec5d04a7509c3fd37',
      version_label='7.5.1 public-source baseline',version_label_basis='research_context_not_binary_identity'},
    runtime_profile={declared_version=U.null,declared_version_basis='not_available',
      api_version=ce_version,file_version=U.null,binary_sha256=U.null},
    source_runtime_equivalence='unverified',
    known_post_source_changes=U.array({
      note('luacode-no-dll-injection','7.5.2','LuaCode no longer requires DLL injection.'),
      note('globalalloc-save','7.6.1','Globalalloc symbols are no longer saved in tables.'),
      note('aa-conditionals-aob','7.6.2','IFDEF/IFNDEF/ENDIF conditionals also apply to AOB scans.'),
      note('aa-hook-unhook','7.6.3','HOOK/UNHOOK commands introduced.'),
      note('aobscanex-executable-fix','7.7.1','Fix for AOBSCANEX not being restricted to executable memory.'),
      note('async-thread-ondestroy','7.7.1','OnDestroy for the asynchronous Memory Record thread.')
    })
  }
end
return M

end
factories['ui'] = function(require, api)
local Export=require('exporter')
local M={}

function M.showReport(Core,api,report)
  if not Core.viewer then
    Core.viewer=Core.state.own(api.createForm(false))
    Core.viewer.Caption='CESuite observation report'
    Core.viewer.Width=900
    Core.viewer.Height=650

    Core.viewer.OnClose=function()
      return caHide
    end

    Core.memo=api.createMemo(Core.viewer)
    Core.memo.Parent=Core.viewer
    Core.memo.Align='alClient'
    Core.memo.ReadOnly=true
    Core.memo.ScrollBars='ssBoth'
    Core.memo.WordWrap=false
  end

  local text=Export.encode(report)

  if Core.memo.Lines then
    Core.memo.Lines.Text=text
  else
    Core.memo.Text=text
  end

  Core.viewer.show()
end

function M.install(Core,api)
  local parent=api.getMainForm().Menu

  for i=0,(parent.Items.Count or 0)-1 do
    assert(
      parent.Items[i].Name~='CESuiteCoreMenu',
      'CESuite menu already exists; restart CE'
    )
  end

  local menu=Core.state.own(api.createMenuItem(parent))
  menu.Caption='CESuite'
  menu.Name='CESuiteCoreMenu'
  parent.Items.add(menu)

  local function command(caption,callback)
    local item=api.createMenuItem(menu)
    item.Caption=caption

    item.OnClick=function()
      local ok,result=pcall(callback)
      if not ok then
        api.showMessage('CESuite: '..tostring(result))
      end
    end

    menu.add(item)
  end

  local function inspect(mode)
    local r=Core.analyze(mode)
    Core.showReport(r)
  end

  command('Analyze Current Process',function()
    inspect('process')
  end)

  command('Analyze Loaded Table',function()
    inspect('table')
  end)

  command('Validate AOBs',function()
    inspect('validate')
  end)

  command('Inspect Selected Script',function()
    inspect('selected')
  end)

  command('Export Analysis Report',function()
    local dialog=api.createSaveDialog(api.getMainForm())

    local ok,err=pcall(function()
      dialog.FileName='CESuite_Runtime_Report.json'
      dialog.DefaultExt='json'
      dialog.Filter='JSON report|*.json'
      dialog.Options='[ofOverwritePrompt,ofPathMustExist]'

      if dialog.execute() then
        Core.export(dialog.FileName)
        api.showMessage('CESuite report saved: '..dialog.FileName)
      end
    end)

    dialog.destroy()

    if not ok then
      error(err)
    end
  end)

  command('About CESuite',function()
    api.showMessage(
      'CESuite '..Core.version..
      ' | '..Core.status..
      ' | '..tostring(Core.distribution)
    )
  end)

  command('Remove CESuite Menu',function()
    Core.shutdown()
  end)

  command('Dependency Summary',function()
    local r=Core.analyze('table')
    Core.showReport({dependency_summary=r.dependency_summary,
      note='Lexical groups only; all unverified. Counts include repeated uses. Occurrence indices refer to dependencies in the full report from this same analysis.'})
  end)

  command('Export Module Dump',function()
    local modules=Core.listDumpModules()
    assert(#modules>0,'No modules available')
    local name=api.inputQuery('Export Module Dump',
      'Attached module name (exact filename):',modules[1].Name)
    if not name or name=='' then return end
    local selected
    for _,module in ipairs(modules) do
      if module.Name:lower()==name:lower() then selected=module;break end
    end
    assert(selected,'Choose a module loaded in the attached process')
    local dialog=api.createSaveDialog(api.getMainForm())
    local ok,err=pcall(function()
      dialog.FileName=selected.Name:gsub('[<>:"/\\|?*]','_')..'.module.bin'
      dialog.DefaultExt='bin'
      dialog.Filter='Mapped module image|*.bin'
      dialog.Options='[ofPathMustExist]'
      if not dialog.execute() then return end
      local progress=api.createForm(false)
      local cancelled=false
      local report
      local dumped,dumpError=pcall(function()
        progress.Caption='CESuite — Export Module Dump'
        progress.Width=470;progress.Height=160
        progress.OnClose=function() cancelled=true;return 0 end
        local label=api.createLabel(progress)
        label.Parent=progress;label.Left=12;label.Top=12
        label.Caption='Preparing module dump...'
        local bar=api.createProgressBar(progress)
        bar.Parent=progress;bar.Left=12;bar.Top=40;bar.Width=430
        bar.Min=0;bar.Max=100
        local cancel=api.createButton(progress)
        cancel.Parent=progress;cancel.Left=12;cancel.Top=78
        cancel.Caption='Cancel'
        cancel.OnClick=function() cancelled=true;cancel.Enabled=false end
        progress.show()
        report=Core.dumpModule(selected.Name,dialog.FileName,{confirmOverwrite=function(files)
          local result=api.messageDialog('These files already exist:\n'..table.concat(files,'\n')..
            '\n\nReplace them? Previous files will be kept with a .previous suffix.',
            api.mtConfirmation or 3,api.mbYes or 0,api.mbNo or 1)
          return result==(api.mrYes or 6)
        end,progress=function(done,total)
          bar.Position=math.floor(done*100/total)
          label.Caption=string.format('%.1f / %.1f MiB (%d%%)',done/1048576,total/1048576,bar.Position)
          -- Explicit export only; Core.state blocks reentrant analysis, dumping
          -- and shutdown while CE processes button/paint events.
          api.processMessages()
          return not cancelled
        end})
      end)
      progress.destroy()
      if not dumped then error(dumpError) end
      if report.status=='cancelled' then
        api.showMessage('CESuite: overwrite cancelled; existing files were kept.')
        return
      end
      api.showMessage('CESuite module dump: '..report.status..
        '\nBytes written: '..tostring(report.bytes_written)..' / '..tostring(report.size)..
        '\nFile: '..report.file..'\nMetadata: '..dialog.FileName..'.json'..
        (report.previous_files and '\nPrevious outputs retained with .previous suffixes (see metadata).' or '')..
        (report.error and ('\nReason: '..report.error) or '')..
        '\nMapped memory image; not a reconstructed executable. Not an atomic snapshot.')
    end)
    dialog.destroy()
    if not ok then error(err) end
  end)

  command('Static Lua AOB Analysis',function()
    local r=Core.analyzeStaticLua()
    Core.showReport(r)
  end)

  command('Export Static Lua Report',function()
    local dialog=api.createSaveDialog(api.getMainForm())
    local ok,err=pcall(function()
      dialog.FileName='CESuite_Runtime_Report_enriched.json'
      dialog.DefaultExt='json'
      dialog.Filter='JSON report|*.json'
      dialog.Options='[ofOverwritePrompt,ofPathMustExist]'
      if dialog.execute() then
        Core.exportEnriched(dialog.FileName)
        api.showMessage('CESuite static Lua report saved: '..dialog.FileName)
      end
    end)
    dialog.destroy()
    if not ok then error(err) end
  end)
end

return M

end
factories['util'] = function(require, api)
local M = {}
M.null = setmetatable({}, {__json_null = true})
function M.array(t) return setmetatable(t or {}, {__json_array = true}) end
function M.trim(s) return (s:gsub('^%s+', ''):gsub('%s+$', '')) end
function M.hex(n) return type(n) == 'number' and string.format('0x%X', n) or M.null end
function M.get(obj, key)
  local ok, value = pcall(function() return obj[key] end)
  if ok then return value end
end
function M.call(api, name, ...)
  if type(api[name]) ~= 'function' then return nil, name .. ' unavailable' end
  local ok, value = pcall(api[name], ...)
  if ok then return value end
  return nil, tostring(value)
end
function M.warn(report, rule, message, script, line)
  table.insert(report.diagnostics, {rule=rule, severity='review', evidence='unverified',
    message=message, script_id=script or M.null, line=line or M.null})
end
function M.number(s)
  s = M.trim(s)
  if s:match('^#%d+$') then return tonumber(s:sub(2), 10) end
  if s:match('^0[xX]%x+$') then return tonumber(s:sub(3), 16) end
  if s:match('^%$%x+$') then return tonumber(s:sub(2), 16) end
  if s:match('^%x+$') then return tonumber(s, 16) end
end
function M.unquote(s)
  local a,b=s:sub(1,1),s:sub(-1)
  if (a=='"' or a=="'") and a==b then return s:sub(2,-2) end
  return s
end
function M.moduleNorm(value)
  if type(value)~='string' then return nil end
  value=M.trim(M.unquote(M.trim(value))):gsub('\\','/'):lower()
  return value~='' and value or nil
end
function M.moduleMatch(query,modules)
  query=M.moduleNorm(query)
  if not query then return nil,'invalid empty module query' end
  local found,count=nil,0
  local basename=not query:find('/',1,true)
  for _,m in ipairs(modules) do
    local name,path=M.moduleNorm(m.name),M.moduleNorm(m.path)
    if name==query or path==query or (basename and
      ((name and name:match('[^/]+$')==query) or (path and path:match('[^/]+$')==query))) then
      found=m;count=count+1
    end
  end
  if count>1 then return nil,'ambiguous module: '..query end
  return found,count==0 and 'unresolved module: '..query or nil
end
return M

end
local api = _G
local function requireModule(name)
  if loaded[name] then return loaded[name] end
  assert(factories[name], 'Unknown CESuite module: '..name)
  loaded[name] = factories[name](requireModule, api)
  return loaded[name]
end
local function entry(require, api)

-- Entry point receives a private module loader and the CE API from the bundle.
local U=require('util')
local Env=require('environment')
local CT=require('ct')
local AOB=require('aob')
local Export=require('exporter')
local Life=require('lifecycle')
local UI=require('ui')
local Dependencies=require('dependencies')
local Semantics=require('semantics')
local ModuleDump=require('moduledump')
local LuaStatic=require('luastatic')
local Core={identity='CESuiteCore',version='0.2.0',schema_version='0.1',status='stopped',state=Life.new()}
local function collectReport(mode)
  local r={schema_version=Core.schema_version,core_version='0.1.9',
    generated_at=os.date('!%Y-%m-%dT%H:%M:%SZ'),mode=mode,observation_only=true,
    records=U.array(),scripts=U.array(),aobs=U.array(),resources=U.array(),dependencies=U.array(),diagnostics=U.array(),
    limitations=U.array({'Dependencies are partial lexical occurrences, not resolved cross-script links or runtime availability; provides/requires remain unverified.',
      'Not an atomic process snapshot; target memory and modules may change during collection.',
      'Uniqueness applies only to CE-readable memory in this scan, not other builds or hook compatibility.',
      'No source scripts, symbol callbacks, includes or macros are executed. Computed expressions can remain unresolved.',
      'Up to 256 addresses per AOB; byte and instruction context omitted because CE disassembly may invoke unaudited callbacks/overrides.',
      'Instruction boundaries, ownership, restore-before-free, overwrite length and relocation safety remain unverified.',
      'CE scan memory-type preferences and unreadable pages can limit coverage; no complete address-space accessibility claim.',
      'Table Lua is unavailable: no audited passive source; Lua Engine editor contents, external Lua files, closures and arbitrary globals are not captured.'})}
  Env.capture(api,r)
  r.semantics_profile=Semantics.profile(r.ce_version)
  if mode~='process' then CT.capture(api,r,mode=='selected') end
  r.dependency_summary=Dependencies.summarize(r.dependencies)
  if mode=='validate' or mode=='export' then AOB.validate(api,r) end
  r.completed_at=os.date('!%Y-%m-%dT%H:%M:%SZ')
  if U.call(api,'getOpenedProcessID')~=r.target.pid then
    U.warn(r,'PROCESS-CHANGED','Process changed during collection; runtime results invalidated.')
    for _,a in ipairs(r.aobs) do a.status='invalidated';a.uniqueness='unverified';a.match_count=U.null;a.matches=U.array();a.hook_candidates=U.array();a.matches_truncated=false end
  end
  Core.last_report=r
  return r
end
function Core.analyze(mode)
  return Core.state.run(function()
    return collectReport(mode)
  end)
end
function Core.analyzeStaticLua()
  return Core.state.run(function()
    local r={schema_version=Core.schema_version,core_version='0.1.9',
      generated_at=os.date('!%Y-%m-%dT%H:%M:%SZ'),mode='table',observation_only=true,
      records=U.array(),scripts=U.array(),aobs=U.array(),resources=U.array(),dependencies=U.array(),diagnostics=U.array(),
      limitations=U.array({
        'Static Lua source candidates only; original runtime aobs and match counts are unchanged.',
        'Library signature declarations remain unlinked when object initialization is unknown.',
        'No target, Lua, cheats, wrappers or scan APIs were executed.',
        'Static source observations are separate from memory-verified AOB matches.'
      })}
    Env.capture(api,r)
    r.semantics_profile=Semantics.profile(r.ce_version)
    CT.capture(api,r,false)
    local observations,diagnostics,limitations=LuaStatic.analyze(r.scripts)
    local patterns={}
    for _,obs in ipairs(observations) do
      if obs.pattern and obs.pattern~=U.null then
        patterns[obs.pattern]=true
      end
    end
    local uniqueCount=0
    for _ in pairs(patterns) do uniqueCount=uniqueCount+1 end
    r.completed_at=os.date('!%Y-%m-%dT%H:%M:%SZ')
    local staticReport={
      title='CESuite Static Lua AOB Analysis',
      core_version='0.1.9',
      suite_version=Core.version,
      ce_version=r.ce_version,
      generated_at=r.generated_at,
      completed_at=r.completed_at,
      observation_only=true,
      target=r.target,
      candidate_count=#observations,
      unique_pattern_count=uniqueCount,
      observations=observations,
      diagnostics=diagnostics,
      limitations=limitations
    }
    Core.last_static_report=staticReport
    return staticReport
  end)
end
function Core.export(path)
  return Core.state.run(function()
    local r=collectReport('export')
    return Export.write(r,path)
  end)
end
function Core.exportEnriched(path)
  return Core.state.run(function()
    local r=collectReport('export')
    LuaStatic.enrichReport(r, nil, Core.version)
    return Export.write(r,path)
  end)
end
function Core.listDumpModules()
  assert(not Core.state.busy,'CESuite is busy')
  return ModuleDump.list(api)
end
function Core.dumpModule(name,path,options) return Core.state.run(function() return ModuleDump.write(api,name,path,options) end) end
function Core.shutdown() Core.state.shutdown();Core.viewer=nil;Core.memo=nil;Core.status='stopped' end
function Core.showReport(report) return UI.showReport(Core,api,report) end
function Core.install()
  if Core.status=='ready' then return Core end
  assert(Core.status~='loading','CESuite menu is already loading')
  Core.status='loading'
  local ok,err=pcall(UI.install,Core,api)
  if not ok then Core.shutdown();error(err) end
  Core.status='ready'
  return Core
end
return Core

end
local version='0.2.0'
local mode='portable'
local function factory() return entry(requireModule,api) end
-- Shared by both distributions. Dependencies are private to each new instance.
local function notify(message)
  if type(api.showMessage)=='function' then pcall(api.showMessage,message)
  elseif type(api.print)=='function' then pcall(api.print,message) end
end
local existing=rawget(api,'CESuiteCore')
if existing~=nil then
  if type(existing)~='table' or existing.identity~='CESuiteCore' then
    local err='CESuiteCore is already occupied (possibly an older Core). Restart CE before upgrading.'
    notify(err);return nil,err
  end
  if existing.version~=version then
    local err='CESuite '..tostring(existing.version)..' is already loaded; requested '..version..'. Restart CE to change versions.'
    notify(err);return existing,err
  end
  local ok,err=pcall(existing.install)
  if not ok then notify('CESuite: '..tostring(err));return nil,err end
  return existing
end
if rawget(api,'CESuiteLoading') then return nil,'CESuite is already loading' end
api.CESuiteLoading=true
local core
local ok,err=pcall(function()
  core=factory()
  assert(core.version==version,'CESuite package version mismatch')
  core.distribution=mode
  core.install()
  api.CESuiteCore=core
end)
api.CESuiteLoading=nil
if not ok then
  if core then pcall(core.shutdown) end
  notify('CESuite failed to load: '..tostring(err))
  return nil,err
end
return core
